code.cpp:
class Solution {
public:
    int findLucky(vector<int>& arr) {
        int cnt[501] = {0};
        for (int x : arr) cnt[x]++;
        int ans = -1;
        for (int i = 1; i <= 500; i++) {
            if (cnt[i] == i) ans = i;
        }
        return ans;
    }
};
